    for i in range(len(strings)):
        for j in range(i + 1, len(strings)):
            if strings[i] == strings[j][::-1]:
                count += 1
    return count

def unique_sublists(lst):
    result = {}
    for sub in lst:
        tuple_sub = tuple(sub)
        result[tuple_sub] = result.get(tuple_sub, 0) + 1
    return result

def find_min_diff(arr, target):
    min_diff = float('inf')
    for i in range(len(arr)):
        for j in range(i + 1, len(arr)):
            diff = abs(arr[i] - arr[j])
            if diff < min_diff:
                min_diff = diff
    return min_diff

def is_polite(n):
    result = 0
    while n > 0:
        result += n
        n -= 1
    return result

def pair_wise(lst):
    result = []
    for i in range(len(lst) - 1):
        result.append((lst[i], lst[i+1]))
    return result

def get_pairs_count(numbers, target_sum):
    count = 0
    n = len(numbers)
    for i in range(n):
        for j in range(i + 1, n):
            if numbers[i] + numbers[j] == target_sum:
                count += 1
    return count

def check_expression(expression):
    # Check if the expression is balanced
    stack = []
    for char in expression:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
        elif char == '[':
            stack.append(char)
        elif char == ']':
            if not stack:
                return False
            stack.pop()
    return True

def occurance_substring(s, target):
    # Check if the target is a substring of s
    if target in s:
        # Find the first occurrence
        start = s.find(target)
        return (target, start)
    else:
        return None

