def find_sum(lst):
    sum = 0
    for num in lst:
        sum += num
    return sum

def pack_consecutive_duplicates(lst):
    result = []
    i = 0
    while i < len(lst):
        j = i
        while j < len(lst) and lst[j] == lst[j - 1]:
            j += 1
        result.append(lst[i:j])
        i = j
    return result

def find_combinations(tuples):
    result = []
    n = len(tuples)
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                for l in range(k + 1, n):
                    if tuples[i][0] + tuples[i][1] == tuples[j][0] + tuples[j][1] and tuples[j][0] + tuples[j][1] == tuples[k][0] + tuples[k][1] and tuples[k][0] + tuples[k][1] == tuples[l][0] + tuples[l][1]:
                        result.append((tuples[i][0], tuples[i][1], tuples[j][0], tuples[j][1], tuples[k][0], tuples[k][1], tuples[l][0], tuples[l][1]))
    return result

def count_divisors(n):
    count = 0
    for i in range(1, n + 1):
        if n % i == 0:
            count += 1
    return count

def odd_length_sum(arr):
    total = 0
    for i in range(len(arr) - 1, 0, -1):
        subarray = arr[i//2]
        total += subarray
    return total

def mul_even_odd(numbers):
    even_product = 1
    odd_product = 1
    for num in numbers:
        if num % 2 == 0:
            even_product *= num
        else:
            odd_product *= num
    return even_product * odd_product

def right_insertion(sorted_list, value):
    # Find the right insertion point using binary search
    left, right = 0, len(sorted_list)
    while left < right:
        mid = (left + right) // 2
        if sorted_list[mid] < value:
            left = mid + 1
        else:
            right = mid
    return left

def even_position(lst):
    for i in range(0, len(lst), 2):
        if lst[i] % 2 != 0:
            return False
    return True

def left_rotate(n, d):
    # Rotate left by d bits
    return int(n >> d) << d

def is_perfect_square(n):
    root = int(n ** 0.5)
    return root * root == n

def is_product_even(numbers):
    product = 1
    for num in numbers:
        product *= num
    return product % 2 == 0

def max_sum_list(list_of_lists):
    max_sum = -float('inf')
    max_list = []

    for sublist in list_of_lists:
        if sum(sublist) > max_sum:
            max_sum = sum(sublist)
            max_list = sublist

    return max_list

def max_run_uppercase(s):
    max_run = 0
    current_run = 0
    for char in s:
        if char.isupper():
            current_run += 1
            max_run = max(max_run, current_run)
        else:
            current_run = 0
    return max_run

